public class ProbeMsPack2283DiagnosticReporting
{
    // A source member in the current compilation with neither Key nor StringKey set
    // is reported by the analyzer as MemberNeedsKey (MsgPack004) at the member identifier.
    // H5 changed this to use DeclaringSyntaxReferences.FirstOrDefault()?.GetSyntax().GetLocation()
    // and H6 added the ReportIfLocatedInCompilation wrapper. If a source property whose
    // declaring syntax reference is present keeps its location, the diagnostic survives.
    // This establishes the baseline the broad filtering in C1 must not disturb.
    [Fact]
    public async Task MsPack004_StillReported_ForSourceMember_NoKeyNoStringKey()
    {
        string source = """
using MessagePack;

namespace TempProject
{
    [MessagePackObject]
    public class MyObject
    {
        public int Unkeyed { get; set; }
    }
}
""";

        var test = new VerifyCS.Test
        {
            LanguageVersion = LanguageVersion.CSharp7_3,
            TestState = { Sources = { source } },
            ExpectedDiagnostics =
            {
                new DiagnosticResult(MsgPack00xMessagePackAnalyzer.MemberNeedsKey)
                    .WithSpan(8, 20, 8, 27)
                    .WithArguments("TempProject.MyObject", "Unkeyed"),
            },
        };
        await test.RunAsync();
    }
}

