using System.Collections.Immutable;
using System.IO;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;
using MessagePack.SourceGenerator;
using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp;
using Microsoft.CodeAnalysis.Diagnostics;
using Microsoft.CodeAnalysis.Testing;
using Xunit;
using AnalyzerOptions = Microsoft.CodeAnalysis.Diagnostics.AnalyzerOptions;

public class ProbeMsPack2283DocClaimUntested
{
    private const string DefineSource = """
using MessagePack;

namespace TempProject
{
    [MessagePackObject]
    public struct MyGenericStruct<T>
    {
        [Key(0)]
        public string Key { get; set; }

        public int Unkeyed { get; set; }
    }
}
""";

    [Fact]
    public async Task MetadataUnkeyedMember_Is_NotReported_Anywhere()
    {
        MetadataReference defining = await CompileMetadata("DefiningProject", DefineSource);

        string usageSource = """
using MessagePack;

namespace TempProject
{
    [MessagePackObject]
    public class MyObject
    {
        [Key(0)]
        public MyGenericStruct<int> Value { get; set; }
    }
}
""";

        ImmutableArray<MetadataReference> framework = await ReferenceAssemblies.Net.Net80.ResolveAsync(LanguageNames.CSharp, CancellationToken.None);
        var parseOptions = CSharpParseOptions.Default.WithLanguageVersion(LanguageVersion.CSharp7_3);
        Compilation compilation = CSharpCompilation.Create(
            "App",
            new[] { CSharpSyntaxTree.ParseText(usageSource, parseOptions) },
            framework.Concat(ReferencesHelper.GetReferences(ReferencesSet.MessagePack)).Append(defining).ToArray(),
            new CSharpCompilationOptions(OutputKind.DynamicallyLinkedLibrary));

        var analyzers = ImmutableArray.Create<DiagnosticAnalyzer>(new global::MessagePack.SourceGenerator.Analyzers.MsgPack00xMessagePackAnalyzer());
        ImmutableArray<Diagnostic> diagnostics = await compilation
            .WithAnalyzers(analyzers, new AnalyzerOptions(ImmutableArray<AdditionalText>.Empty))
            .GetAnalyzerDiagnosticsAsync(CancellationToken.None);

        // README claims the defining assembly reports the metadata member diagnostic.
        // The defining assembly was emitted without running analyzers, so no diagnostic for Unkeyed exists anywhere.
        Assert.DoesNotContain(diagnostics, d => d.ToString().Contains("Unkeyed"));
    }

    private static async Task<MetadataReference> CompileMetadata(string assemblyName, string source)
    {
        ImmutableArray<MetadataReference> framework = await ReferenceAssemblies.Net.Net80.ResolveAsync(LanguageNames.CSharp, CancellationToken.None);
        var parseOptions = CSharpParseOptions.Default.WithLanguageVersion(LanguageVersion.CSharp7_3);
        CSharpCompilation compilation = CSharpCompilation.Create(
            assemblyName,
            new[] { CSharpSyntaxTree.ParseText(source, parseOptions) },
            framework.Concat(ReferencesHelper.GetReferences(ReferencesSet.MessagePack)).ToArray(),
            new CSharpCompilationOptions(OutputKind.DynamicallyLinkedLibrary));
        using var stream = new MemoryStream();
        Microsoft.CodeAnalysis.Emit.EmitResult emit = compilation.Emit(stream);
        Assert.True(emit.Success, string.Join("\n", emit.Diagnostics));
        return MetadataReference.CreateFromImage(stream.ToArray());
    }
}
